insert into public.services (slug, title, display, short_description, full_description, points, symbol, published, display_order, seo_title, seo_description) values
  ('website-design', 'Website Design', 'Website|Design', 'Interfaces shaped around your business.', 'Modern UI/UX and visual systems designed around your brand, your audience and the one action you need visitors to take.

We start from how your customers decide, then shape the layout, typography and visual direction around that decision — so the site looks like you and works for you.', array['UI / UX design', 'Visual direction', 'Design systems']::text[], 'design', true, 1, null, null),
  ('web-development', 'Web Development', 'Web|Development', 'Production-ready, from the first commit.', 'Responsive, scalable websites built with clean, maintainable code — engineered to load fast and hold up as you grow.

From static marketing sites to custom web applications with logins, dashboards and databases, we build what the project needs and nothing it doesn''t.', array['Responsive builds', 'Clean code', 'Deployment']::text[], 'development', true, 2, null, null),
  ('business-websites', 'Business Websites', 'Business|Websites', 'Credibility, on every screen.', 'Professional websites that tell your story clearly, earn trust in seconds and turn visitors into enquiries.

Services, portfolio, contact and quote forms — structured so a visitor always knows what you do and how to reach you.', array['Clear messaging', 'Enquiry flows', 'Local presence']::text[], 'business', true, 3, null, null),
  ('ecommerce-development', 'E-commerce Development', 'E-commerce|Development', 'Storefronts built to sell.', 'Modern online stores designed around your products — clean browsing, confident checkout, fewer abandoned carts.

Product catalogues, wishlists, payments and order tracking, designed mobile-first because that''s where your customers shop.', array['Product catalogues', 'Checkout UX', 'Mobile-first']::text[], 'ecommerce', true, 4, null, null),
  ('landing-pages', 'Landing Pages', 'Landing|Pages', 'One page. One job. Done well.', 'Focused pages for launches, campaigns, products and lead generation — built to convert, measured to improve.

One message, one action, no distractions.', array['Campaign pages', 'Lead capture', 'A/B-ready']::text[], 'landing', true, 5, null, null),
  ('website-redesign', 'Website Redesign', 'Website|Redesign', 'Old site, new standard.', 'We take outdated websites and rebuild them into modern experiences — keeping what works, fixing what doesn''t.

We review what your current site does well, then rebuild the rest with a modern design and a faster, cleaner codebase.', array['UX audit', 'Visual refresh', 'Rebuild']::text[], 'redesign', true, 6, null, null),
  ('android-apps', 'Android Apps', 'Android|Apps', 'Your business, in your customer''s pocket.', 'Android apps for businesses that want to be one tap away — designed around your brand and published on Google Play.

We can build the app alongside your website so both tell the same story.', array['Android apps', 'Google Play release', 'Brand-first UI']::text[], 'android', true, 7, null, null),
  ('performance-optimization', 'Performance Optimization', 'Performance|Optimization', 'Every millisecond counts.', 'We tune speed, responsiveness and Core Web Vitals so your site feels instant — for users and for search engines.

Images, fonts, scripts and hosting: we find what slows your pages down and fix it.', array['Core Web Vitals', 'Asset optimisation', 'Technical SEO']::text[], 'performance', true, 8, null, null),
  ('maintenance-support', 'Maintenance & Support', 'Maintenance|& Support', 'We don''t disappear after launch.', 'Ongoing updates, fixes, improvements and technical support — so your website keeps working as hard as you do.

Content updates, new sections, fixes and technical help when you need it.', array['Updates & fixes', 'Improvements', 'Technical support']::text[], 'support', true, 9, null, null)
on conflict (slug) do nothing;

insert into public.process_steps (name, description, published, display_order)
select * from (values
  ('Discover', 'We learn your business, audience, objectives and requirements — before a single pixel is placed.', true, 1),
  ('Design', 'We establish the visual direction and user experience, and refine it with you until it''s right.', true, 2),
  ('Develop', 'We turn the approved design into a fast, responsive, production-ready website.', true, 3),
  ('Test', 'We check responsiveness, usability, functionality and performance across devices and browsers.', true, 4),
  ('Launch', 'We prepare, configure and deploy the production website — then watch it go live.', true, 5),
  ('Improve', 'We keep refining the site when you need it: new features, updates and optimisations.', true, 6)
) as v (name, description, published, display_order)
where not exists (select 1 from public.process_steps);

insert into public.content_sections (key, data) values
  ('hero', '{"meta_1":"/ Digital foundry","meta_2":"India / Worldwide","serif":"Impossible to ignore.","heading":"We build websites that make businesses impossible to ignore.","description":"Modern, fast, responsive digital experiences — designed and developed for businesses, brands, startups and entrepreneurs.","primary_cta":"Start a project","secondary_cta":"View our work"}'::jsonb),
  ('philosophy', '{"lead":"Your website isn''t just a page on the internet. It''s","statement_1":"Your digital","statement_2":"first impression.","description":"Visitors decide in seconds whether to trust you. We make those seconds count — by treating design, development, performance and usability as one discipline, not four separate jobs.","design":"Interfaces with a point of view — clear, considered, unmistakably yours.","develop":"Clean, responsive builds that behave on every screen size.","perform":"Lightweight pages that load fast and stay fast.","convert":"Obvious paths to the one thing you want visitors to do."}'::jsonb),
  ('work', '{"description":"Real projects on real domains. Don''t take our word for it — click through and judge for yourself."}'::jsonb),
  ('apps', '{"description":"Not just websites. We build Android apps too — designed around the brand and published on Google Play."}'::jsonb),
  ('services', '{"heading":"Everything your website needs.","highlight":"Nothing it doesn''t.","description":"From the first sketch to ongoing support — one lab, one standard, end to end."}'::jsonb),
  ('about', '{"statement_1":"A small lab","statement_2":"with a serious standard.","paragraphs":"Rudra InfoTech Lab is a web design and development studio. We build websites for businesses, brands, startups and entrepreneurs who want more from the web than a page that simply exists.\n\nWe work like a lab: curious, hands-on and a little obsessive about the details. You talk directly to the people designing your pages and writing your code — so ideas don''t get lost in translation.\n\nSmall enough to care about your project personally. Technical enough to build it properly.","what_we_do":"Website design & development","who_its_for":"Businesses, brands, startups & entrepreneurs","how_we_work":"Directly, transparently, end to end"}'::jsonb),
  ('contact', '{"heading_1":"Have","heading_2":"an idea?","serif":"Let''s build it.","description":"A few details are all we need. We''ll read every word, then reply with honest next steps — no jargon, no pressure.","button":"Send the brief","whatsapp_cta":"Chat on WhatsApp","success_title":"Brief received.","success_text":"Thanks — your project is in the lab. We''ll get back to you shortly with next steps."}'::jsonb),
  ('footer', '{"statement":"Make something worth visiting.","tagline":"Web design & development studio"}'::jsonb)
on conflict (key) do nothing;

