values (1, 'Rudra InfoTech Lab — Web Design & Development Agency', 'Web development agency building fast, responsive, business-focused websites and Android apps: business sites, e-commerce, landing pages, redesigns and custom builds.', '', 'Rudra InfoTech Lab — Websites & apps that make businesses impossible to ignore', 'A web design and development lab building fast, responsive websites and Android apps for businesses, brands, startups and entrepreneurs.', '/og-v3.png', '/og-v3.png', '', '', true)
